SELECT band.name, band.country, album.title, album.release_date, band.studio_album_count
FROM band
JOIN album ON band.id = album.band_id
WHERE album.title = 'My Animal' AND band.country = 'United States' AND album.release_date BETWEEN '2003-03-01' AND '2003-05-31';

SELECT COUNT(studio_album.id) FROM album AS studio_album
JOIN band ON studio_album.band_id = band.id
WHERE band.name = (name_of_band_that_released_my_animal);

SELECT COUNT(studio_album.id) FROM album AS studio_album
JOIN band ON studio_album.band_id = band.id
WHERE band.name = 'The Invisible';

SELECT ?cityProfessor ?cityChurch WHERE {
  ?professor a dbo:Professor ;
             dbo:birthName "Nancy R. Howell" ;
             dbo:employer ?college .
  ?college dbo:city ?cityProfessor .
  ?church dbo:name "United Methodist Church of the Resurrection" ;
          dbo:city ?cityChurch .
  FILTER(CONTAINS(LCASE(STR(?cityProfessor)), "kansas") || CONTAINS(LCASE(STR(?cityChurch)), "kansas"))
}

