SELECT ?town ?bandFormationYear WHERE {
  ?station wdt:P31 wd:Q19661324;  # instance of TV station
           rdfs:label "WCJB-TV"@en;
           wdt:P131 ?town.           # located in administrative entity (town/licensee)
  ?town rdfs:label ?townName.

  ?band wdt:P31 wd:Q215380;          # instance of band
        rdfs:label "Against Me!"@en;
        wdt:P571 ?bandFormationDate;
        wdt:P740 ?bandHometown.     # place of formation

  FILTER(CONTAINS(LCASE(?townName), "gainesville"))
  FILTER(?town = ?bandHometown)

  BIND(YEAR(?bandFormationDate) AS ?bandFormationYear)
}
LIMIT 1

SELECT ?band WHERE {
  ?band wdt:P31 wd:Q215380;                  # instance of band
        wdt:P27 wd:Q30;                      # country of origin is United States
        wdt:P136 wd:Q11399.                  # genre includes rock music
  ?song wdt:P175 ?band;                      # song performed by band
        rdfs:label "My Animal"@en;
        wdt:P577 ?releaseDate.               # publication date
  FILTER(YEAR(?releaseDate) = 2003 && MONTH(?releaseDate) >= 3 && MONTH(?releaseDate) <= 5)  # spring months
  # Count studio albums for the band
  {
    SELECT ?band (COUNT(?album1) AS ?bandAlbumCount) WHERE {
      ?album1 wdt:P31 wd:Q482994;            # instance of studio album
              wdt:P175 ?band.
    } GROUP BY ?band
  }
  # Count studio albums for The Invisible
  {
    SELECT ?invisibleAlbumCount WHERE {
      ?invisibleBand rdfs:label "The Invisible"@en.
      ?album2 wdt:P31 wd:Q482994;
              wdt:P175 ?invisibleBand.
    } GROUP BY ?invisibleBand
    HAVING(COUNT(?album2) AS ?invisibleAlbumCount)
  }
  FILTER(?bandAlbumCount > ?invisibleAlbumCount)
}

SELECT 
  (SELECT city FROM colleges WHERE professor_name = 'Nancy R. Howell' AND department = 'Theology' LIMIT 1) AS professor_city,
  (SELECT city FROM churches WHERE name = 'United Methodist Church of the Resurrection' LIMIT 1) AS church_city;

SELECT 
  (SELECT city FROM colleges WHERE professor_name = 'Nancy R. Howell' AND subject = 'Theology') AS college_city,
  (SELECT city FROM churches WHERE name = 'United Methodist Church of the Resurrection') AS church_city;
